def best_cell(sugar, loc, vision, occupied):
    n, m = sugar.shape
    r, c = loc
    candidates = [(0, loc)]
    for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
        for d in range(1, vision + 1):
            cell = ((r + dr * d) % n, (c + dc * d) % m)
            if cell not in occupied:
                candidates.append((d, cell))
    best = max(candidates, key=lambda dc: (sugar[dc[1]], -dc[0]))
    return best[1]

